#!/usr/bin/env python3
# Generated by `verdant-studio publish` from studio/src/Studio/Ops.lex.tex. Do not edit.
# The owner's acceptance test for the whole pipeline (REQ-SELF-HOSTED, REQ-PRISM-GENERATION): prompt Studio
# with the seed "Verdant Studio" and require every facet the Prism lists to have its media type at the
# fidelity its generator's theorems state. Run from the repository root after the build, so the app is not
# proved again: prism-acceptance.py COMMAND... runs COMMAND run app --input REQUEST for each request.
import struct, subprocess, sys, xml.etree.ElementTree as tree
SEED = 'Verdant Studio'
MIDI_HEADER = bytes.fromhex('4d54686400000006000000010060')
FMT = bytes.fromhex('0100010080bb00000077010002001000')
SVG_ROOT = '{http:' + chr(47) * 2 + 'www.w3.org' + chr(47) + '2000' + chr(47) + 'svg}svg'

def run(request):
    got = subprocess.run(sys.argv[1:] + ['run', 'app', '--input', request, '--rm'], capture_output=True)
    if got.returncode != 0:
        raise SystemExit('::error::' + repr(request) + ' failed: ' + got.stderr.decode(errors='replace')[-400:])
    return got.stdout

def midi(data):
    # Midi.lex.tex writes_a_format_0_file: format 0, one track, 96 ticks per quarter note.
    if not data.startswith(MIDI_HEADER) or data[14:18] != b'MTrk':
        return 'is no format 0 SMF with one track at 96 ticks per quarter note'
    if struct.unpack('>I', data[18:22])[0] != len(data) - 22:
        return 'has a track length that is not the rest of the file'

def wave(data):
    # Bwf.lex.tex format_is_pcm_mono_48000_16 and wave_orders_bext_fmt_data: bext (646 bytes), fmt, data.
    if data[:4] != b'RIFF' or data[8:12] != b'WAVE' or struct.unpack('<I', data[4:8])[0] != len(data) - 8:
        return 'is no RIFF WAVE file of its own length'
    chunks, at = [], 12
    while at + 8 <= len(data):
        name, size = data[at:at + 4], struct.unpack('<I', data[at + 4:at + 8])[0]
        chunks.append((name, data[at + 8:at + 8 + size]))
        at += 8 + size + (size & 1)
    if [name for name, body in chunks] != [b'bext', b'fmt ', b'data']:
        return 'has chunks ' + repr([name for name, body in chunks]) + ', not bext, fmt and data'
    if len(chunks[0][1]) != 646:
        return 'has a bext chunk of ' + str(len(chunks[0][1])) + ' bytes, not 646'
    if chunks[1][1] != FMT:
        return 'is not PCM, mono, 48000 Hz, 16-bit'
    if not chunks[2][1]:
        return 'has no samples'

def svg(data):
    try:
        root = tree.fromstring(data)
    except tree.ParseError as failure:
        return 'is not well-formed XML: ' + str(failure)
    if root.tag != SVG_ROOT:
        return 'has the root ' + root.tag + ', not svg in the SVG namespace'

def bundle(data):
    if data[:4] != b'PK' + bytes([3, 4]) or b'bagit.txt' not in data:
        return 'is no ZIP holding a BagIt bag'

RULES = {'audio/midi': midi, 'audio/wave': wave, 'image/svg+xml': svg, 'application/zip': bundle}
facets = [line for line in run('prism' + chr(9) + chr(9) + SEED).decode().split(chr(10)) if line]
if not facets:
    raise SystemExit('::error::the Prism of ' + SEED + ' lists no facet')
failed = False
for facet in facets:
    data = run('prism' + chr(9) + facet + chr(9) + SEED)
    rule = RULES.get(facet)
    problem = 'has no acceptance rule, so its fidelity is unchecked' if rule is None else rule(data)
    if problem:
        failed = True
        print('::error::the ' + facet + ' facet of ' + SEED + ' ' + problem)
    else:
        print('accepted: the ' + facet + ' facet of ' + SEED + ', ' + str(len(data)) + ' bytes')
sys.exit(1 if failed else 0)
